const r=screen("Variant B · Workspace rail + Site tree",1540,0);
const rail=fr(r,"Workspace rail",{layout:"vertical",width:64,height:"fill_container",fill:"$sidebar",stroke:"$border",strokeWidth:{right:1},padding:[14,0],gap:12,alignItems:"center"});
const lg=fr(rail,"Logo",{width:36,height:36,cornerRadius:9,fill:"$primary",alignItems:"center",justifyContent:"center"});tx(lg,"W",{fontWeight:"700",fontSize:16,fill:"$primary-fg"});
fr(rail,"Rail divider",{width:28,height:1,fill:"$border"});
avatar(rail,"AC",{square:true,size:36,fill:"#D97706",ring:true,fs:12});avatar(rail,"NB",{square:true,size:36,fill:"#059669",fs:12});avatar(rail,"VT",{square:true,size:36,fill:"#7C3AED",fs:12});avatar(rail,"OS",{square:true,size:36,fill:"#DB2777",fs:12});
const add=fr(rail,"Add Workspace",{width:36,height:36,cornerRadius:9,stroke:"$border",strokeWidth:1,alignItems:"center",justifyContent:"center"});ic(add,"plus");
vsp(rail);
const sa=fr(rail,"Superadmin",{width:36,height:36,cornerRadius:9,alignItems:"center",justifyContent:"center"});ic(sa,"shield",{width:18,height:18});
const st=fr(rail,"Install settings",{width:36,height:36,cornerRadius:9,alignItems:"center",justifyContent:"center"});ic(st,"settings",{width:18,height:18});
avatar(rail,"DD",{fill:"#0EA5E9",size:32});
const sb=fr(r,"Workspace sidebar",{layout:"vertical",width:256,height:"fill_container",fill:"$sidebar",stroke:"$border",strokeWidth:{right:1},padding:12,gap:8});
const h=fr(sb,"Workspace header",{width:"fill_container",padding:[6,8],alignItems:"center",gap:8});const hc=fr(h,"Names",{layout:"vertical",width:"fill_container",gap:1});tx(hc,"Acme Ltd",{fontWeight:"600",fontSize:15});tx(hc,"Workspace · 3 Sites",{fontSize:12,fill:"$muted-fg"});ic(h,"chevron-down");
input(sb,"Search",{icon:"search",kbd:"⌘K"});
const S=section(sb,"Sites");
const site=(name,dot,open)=>{const row=fr(S,"Site "+name,{width:"fill_container",height:30,gap:8,padding:[0,8],alignItems:"center",cornerRadius:6});ic(row,open?"chevron-down":"chevron-right",{width:14,height:14});Insert(row,{type:"ellipse",name:"Dot",width:8,height:8,fill:dot});tx(row,name,{fontWeight:open?"600":"400",fill:open?"$fg":"$muted-fg"});};
site("Acme Bakery","#16A34A",true);
for(const [i,l,o] of [["file-text","Pages",{badge:12}],["newspaper","Blog posts",{badge:24,active:true}],["users","Team",{badge:8}],["image","Media"],["inbox","Forms",{tag:"5 new",tagKind:"info"}],["sliders-horizontal","Globals"],["languages","Translations",{tag:"2",tagKind:"warn"}]])nav(S,i,l,{...o,indent:22});
const bh=fr(S,"Build heading",{width:"fill_container",padding:[8,8,2,30],gap:6,alignItems:"center"});tx(bh,"Build",{fontSize:11,fontWeight:"500",fill:"$muted-fg"});sp(bh);badge(bh,"Staff only","outline");
for(const [i,l] of [["database","Post Types & Fields"],["layout-template","Templates"],["component","Components"],["palette","Design system"],["settings","Site settings"]])nav(S,i,l,{indent:22});
site("Acme Careers","#16A34A",false);site("Acme Catering","#F59E0B",false);
const W=section(sb,"Workspace");for(const [i,l,o] of [["users","Members",{badge:7}],["shield-check","Protected terms"],["key-round","AI keys"],["scroll-text","Audit log"]])nav(W,i,l,o);
const m=mainCol(r);
const t=fr(m,"Top bar",{width:"fill_container",height:52,padding:[0,16,0,24],alignItems:"center",gap:10,stroke:"$border",strokeWidth:{bottom:1}});
const chip=fr(t,"Site chip",{gap:8,alignItems:"center",padding:[4,10],cornerRadius:999,fill:"$muted"});Insert(chip,{type:"ellipse",name:"Dot",width:8,height:8,fill:"#16A34A"});tx(chip,"acmebakery.ie",{fontSize:12,fontWeight:"500"});ic(chip,"external-link",{width:12,height:12});
sp(t);btn(t,"Staging",{kind:"ghost",icon:"eye"});btn(t,"Edit on site",{icon:"mouse-pointer-click"});btn(t,"Publish all",{kind:"primary",icon:"upload",count:5});
entries(m);
Export([r],"png","/tmp/penproto/out");
